// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000000);

        vm.prank(address(1));
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.prank(address(1));
        c.collectDrugs(address(0));

        uint256 bonus = c.claimedDrugs(address(0));
        assertTrue(bonus > 0, "Reference: address(0) should have received referral bonus");
    }
}
